#!/usr/bin/env bash
# ownerfree — מריץ 11 (שמוליק → חינם, אישור הבעלים 22.10) ומאמת את ההרשאות לפי מסלול חינם. מדפיס רק מסלולים/דגלים, בלי פרטים אישיים.
RO="https://api.supabase.com/v1/projects/$PROD_REF/database/query/read-only"; RW="https://api.supabase.com/v1/projects/$PROD_REF/database/query"
[ "${REVERIFY:-}" ] || { C=$(curl -sS -m 60 -o /tmp/of.json -w '%{http_code}' -X POST -H "Authorization: Bearer $TOK" -H 'Content-Type: application/json' "$RW" -d "$(jq -nc --rawfile q "$ROOT/supabase/production/11_owner_to_free.sql" '{query:$q}')" || echo 000); [ "$C" = 201 ] || [ "$C" = 200 ] || stop "11 נכשל — לא נשמר כלום: HTTP $C $(jq -r '.message // empty' /tmp/of.json | cut -c1-300)"; }
Q="select (select row_to_json(o) from (select plan, status, source, current_period_end, auto_renew from public.hdm_subscriptions where profile_id='reg_mupj1bkt75rzke') o) owner_sub, (select row_to_json(p) from public.hdm_plans p where plan = (select plan from public.hdm_subscriptions where profile_id='reg_mupj1bkt75rzke')) owner_perms, (select count(*) from public.hdm_accounts where profile_id='reg_mupj1bkt75rzke') owner_account, (select json_object_agg(plan, n) from (select plan, count(*) n from public.hdm_subscriptions group by plan) z) plans_count, (select count(*) from auth.users) auth_users, (select count(*) from public.docs where collection='profiles') profiles"
C=$(curl -sS -m 60 -o /tmp/of.json -w '%{http_code}' -X POST -H "Authorization: Bearer $TOK" -H 'Content-Type: application/json' "$RO" -d "$(jq -nc --arg q "$Q" '{query:$q}')" || echo 000)
ann notice "owner-free" "HTTP $C $(jq -c '.[0]' /tmp/of.json)"
ann notice "prod-result" "✅ ownerfree: שמוליק במסלול חינם"
